const body = $input.first().json.body || $input.first().json;

if (body?.tool !== 'evtx-hunter' || !Array.isArray(body?.findings) || body.findings.length === 0) {
  return [{ json: { _valid: false, _code: 400, _reason: 'Expected tool="evtx-hunter" and a non-empty findings array' } }];
}

const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
const trunc = (s, n) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n) + '...' : s; };
const fmt = e => (e && typeof e === 'object') ? Object.entries(e).map(([k, v]) => `${k}=${v}`).join(', ') : String(e ?? '');

const findings = body.findings.slice(0, 50).map(f => ({
  rule_id: String(f?.rule_id ?? ''),
  title: String(f?.title ?? 'Untitled finding'),
  level: f?.level ?? '',
  attack: Array.isArray(f?.attack) ? f.attack.map(String) : [],
  time: String(f?.time ?? ''),
  host: String(f?.host ?? ''),
  event_count: Number(f?.event_count ?? 0),
  evidence: Array.isArray(f?.evidence) ? f.evidence.slice(0, 3).map(e => trunc(fmt(e), 300)) : [],
}));

const sevRaw = Number(body?.summary?.thehive_severity);
const severity = clamp(Number.isFinite(sevRaw) ? sevRaw : 2, 1, 4);

const hosts = Array.isArray(body?.summary?.hosts) ? body.summary.hosts.map(String) : [];
const hostsLabel = hosts.length ? hosts.join(', ') : 'unknown host(s)';
const n = findings.length;
const attackIds = [...new Set(findings.flatMap(f => f.attack))].filter(Boolean);

const rows = findings.map(f => `| ${f.time} | ${f.host} | ${f.level} | ${f.title.split('|').join('&#124;')} | ${f.attack.join(', ')} |`).join('\n');
const evidenceBlocks = findings.map(f => {
  const lines = f.evidence.map(e => '    ' + e).join('\n');
  return `**${f.title}** (${f.host} @ ${f.time})\n${lines || '    (no evidence lines)'}`;
}).join('\n\n');

const description = [
  `# EVTX Hunter - ${n} finding(s) on ${hostsLabel}`,
  `Generated: ${String(body?.generated ?? '')}  |  Tool v${String(body?.version ?? '')}`,
  '',
  '| Time | Host | Level | Title | ATT&CK |',
  '|---|---|---|---|---|',
  rows,
  '',
  '## Evidence (first 3 lines per finding)',
  evidenceBlocks,
].join('\n');

function hashHex(str) {
  let h1 = 0x811c9dc5, h2 = 0xc9dc5118;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193);
    h2 = Math.imul(h2 ^ c, 0x01000193) + i;
  }
  const hx = x => (x >>> 0).toString(16).padStart(8, '0');
  return hx(h1) + hx(h2);
}
const key = findings.map(f => `${f.rule_id}|${f.time}|${f.host}`).sort().join('\n');
const sourceRef = 'evtx-hunter-' + hashHex(key);

const alert = {
  title: `EVTX Hunter: ${n} finding${n === 1 ? '' : 's'} on ${hostsLabel}`,
  description,
  type: 'evtx-hunter',
  source: 'evtx-hunter-cli',
  sourceRef,
  severity,
  tlp: 2,
  tags: ['evtx-hunter', ...attackIds],
  observables: hosts.map(h => ({ dataType: 'hostname', data: h, tags: ['evtx-hunter'] })),
};

return [{ json: { _valid: true, _code: 200, severity, sourceRef, _alert_body: JSON.stringify(alert) } }];

const built = $('Validate & Build').item.json;
const res = $input.first().json;
const sc = res?.statusCode ?? res?.status ?? 0;
const data = res?.body ?? res;
const alertId = data?._id || data?.id;
if (sc >= 200 && sc < 300 && alertId) {
  return [{ json: { _code: 200, status: 'created', alertId, sourceRef: built.sourceRef } }];
}
const msg = JSON.stringify(data?.message || data?.type || data || {});
const isDuplicate = sc === 409 || /already exists|duplicate|conflict/i.test(msg);
if (isDuplicate) {
  return [{ json: { _code: 200, status: 'duplicate', duplicate: true, sourceRef: built.sourceRef } }];
}
return [{ json: { _code: 502, status: 'error', reason: 'TheHive alert creation failed', http_status: sc, detail: msg.slice(0, 500) } }];
